-- Unlocked SAT — starter question bank (56 original questions).
-- Generated by scripts/gen-seed.mts. Run after schema.sql in Supabase → SQL Editor.
-- Existing rows with the same id are left untouched, so it is safe to re-run.

insert into public.questions (id, section, skill, difficulty, passage, prompt, choices, answer, accept, explanation, status)
values
  ('rw01', 'rw', 'words-in-context', 1, 'The new community library was designed to be ______: its reading rooms, study spaces, and children’s area can all be rearranged within an hour to host lectures, workshops, or exhibitions.', 'Which choice completes the text with the most logical and precise word or phrase?', '["adaptable","permanent","obscure","fragile"]'::jsonb, 0, null, 'The colon introduces evidence that the spaces can be quickly rearranged for different uses. “Adaptable” (able to change for new purposes) matches. Nothing suggests the building is fragile, hard to find (obscure), or unchanging (permanent).', 'published'),
  ('rw02', 'rw', 'boundaries', 1, 'Samarkand’s Registan square is framed by three madrasas, the oldest ______ completed in 1420 under the patronage of Ulugh Beg.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["of which was","of which, was","which was","of which; was"]'::jsonb, 0, null, '“The oldest of which was completed…” is a correct relative phrase that describes the madrasas. No punctuation belongs between the subject (“the oldest of which”) and its verb (“was”). “Which was” alone would not make sense after “the oldest.”', 'published'),
  ('rw03', 'rw', 'transitions', 2, 'Desert plants often store water in thick, fleshy leaves. ______ the aloe vera plant can survive several months without rain by drawing on the gel stored inside its leaves.', 'Which choice completes the text with the most logical transition?', '["In contrast,","Nevertheless,","For example,","However,"]'::jsonb, 2, null, 'The second sentence gives a specific case (aloe vera) of the general claim in the first sentence, so “For example” is the logical transition. The other choices signal contrast, which is not present.', 'published'),
  ('rw04', 'rw', 'central-ideas', 2, 'An economist studied small family shops in Tashkent that began accepting mobile payments. She found that, within a year, these shops attracted noticeably more customers under the age of thirty than similar shops that accepted only cash, while their sales to older customers stayed about the same. She suggests that offering mobile payment may help shops reach younger shoppers without losing older ones.', 'Which choice best states the main idea of the text?', '["Shops that accept only cash earn more than shops that accept mobile payments.","Most small family shops in Tashkent now accept only mobile payments.","Adding mobile payments may help small shops gain younger customers while keeping older ones.","Older customers in Tashkent refuse to use mobile payments."]'::jsonb, 2, null, 'The text reports more young customers and unchanged sales to older customers, and ends with the economist’s conclusion that mobile payment can attract younger shoppers without losing older ones. The other choices make claims the text never supports.', 'published'),
  ('rw05', 'rw', 'form-structure-sense', 2, 'The collection of handwritten letters, which spans more than four decades of the poet’s life, ______ now available to researchers in digitized form.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were","have been","are","is"]'::jsonb, 3, null, 'The subject is the singular noun “collection,” not “letters.” A singular subject needs the singular verb “is.” The phrase “of handwritten letters” and the clause between commas do not change the subject.', 'published'),
  ('rw06', 'rw', 'inferences', 3, 'When honeybees find a rich source of food, they return to the hive and perform a “waggle dance” that signals the food’s direction and distance to other bees. Researchers observed that in hives where bees could not perceive the dance—because the hive was kept dark and the dancers’ vibrations were blocked—foragers took much longer to find new food sources. This suggests that ______', 'Which choice most logically completes the text?', '["honeybees cannot find food without light.","the waggle dance helps other bees locate food more efficiently.","the distance to food has no effect on how bees dance.","bees that perform the waggle dance gather more food than other bees."]'::jsonb, 1, null, 'When bees could not perceive the dance, finding food took longer. The logical conclusion is that the dance helps bees find food faster. The bees still found food, so “cannot find food without light” goes too far, and nothing compares dancers with non-dancers.', 'published'),
  ('rw07', 'rw', 'rhetorical-synthesis', 3, 'While researching a topic, a student has taken the following notes:
• The Aral Sea was once the fourth-largest lake in the world.
• Beginning in the 1960s, rivers feeding the sea were diverted to irrigate cotton fields.
• By 2010, the sea had shrunk to roughly 10% of its original area.
• The Kokaral Dam, completed in 2005, helped the northern part of the sea partially recover.', 'The student wants to emphasize a hopeful development. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["After the Kokaral Dam was completed in 2005, the northern part of the Aral Sea partially recovered.","The Aral Sea was once the fourth-largest lake in the world.","The Aral Sea, once the fourth-largest lake in the world, had shrunk to about 10% of its original area by 2010.","Beginning in the 1960s, rivers feeding the Aral Sea were diverted to irrigate cotton fields."]'::jsonb, 0, null, 'Only the partial recovery of the northern sea after the dam is a hopeful development. The other choices describe the lake’s former size or its decline.', 'published'),
  ('rw08', 'rw', 'words-in-context', 1, 'Because the bridge was closed for repairs, drivers had to take a ______ route that added twenty minutes to their trip.', 'Which choice completes the text with the most logical and precise word or phrase?', '["roundabout","direct","brief","familiar"]'::jsonb, 0, null, 'A route that adds twenty minutes is indirect, or “roundabout.” “Direct” and “brief” contradict the extra time, and nothing indicates the route was familiar.', 'published'),
  ('rw09', 'rw', 'boundaries', 1, 'Apricots are grown in many countries, but world production is led by a small ______ Turkey, Uzbekistan, and Iran are consistently among the largest producers.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["group,","group:","group","group and"]'::jsonb, 1, null, 'Both parts are complete sentences, and the second explains which countries form the group. A colon correctly joins them. No punctuation or a comma alone would create a run-on or comma splice.', 'published'),
  ('rw10', 'rw', 'transitions', 1, 'Madina wanted to see the sunrise from the top of the mountain. ______ she set her alarm for 4:00 a.m.', 'Which choice completes the text with the most logical transition?', '["However,","Therefore,","Similarly,","Instead,"]'::jsonb, 1, null, 'Setting the alarm early is a result of wanting to see the sunrise, so “Therefore” shows the cause-and-effect relationship.', 'published'),
  ('rw11', 'rw', 'central-ideas', 2, 'Many people assume that the best way to memorize information is to reread it several times. However, studies of learning have repeatedly found that testing yourself—trying to recall information without looking—leads to better long-term memory than rereading does. This “testing effect” appears even when the self-tests are short and when learners get some answers wrong.', 'Which choice best states the main idea of the text?', '["Rereading is the most popular study method because it is effective.","Learners should avoid getting answers wrong on practice tests.","Short tests are less useful than long tests.","Testing yourself tends to improve long-term memory more than rereading does."]'::jsonb, 3, null, 'The text challenges the assumption about rereading and reports that self-testing produces better long-term memory. The other choices contradict the text or are not discussed.', 'published'),
  ('rw12', 'rw', 'form-structure-sense', 2, 'Last summer, a team of student volunteers ______ more than two hundred trees around their school.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["plants","will plant","is planting","planted"]'::jsonb, 3, null, '“Last summer” places the action in the past, so the past-tense verb “planted” is required.', 'published'),
  ('rw13', 'rw', 'command-of-evidence', 2, 'A student claims that octopuses are capable of solving problems.', 'Which finding, if true, would most directly support the student’s claim?', '["Octopuses have three hearts.","Some species of octopus live for only about a year.","Octopuses can change the color of their skin.","In experiments, octopuses learned to unscrew jar lids to reach food inside."]'::jsonb, 3, null, 'Unscrewing a lid to reach food is an example of solving a problem. The other facts are true of many octopuses but say nothing about problem-solving.', 'published'),
  ('rw14', 'rw', 'text-structure', 2, 'Aziz had practised the piece for months, yet when he sat down at the piano in front of the audience, his hands felt like someone else’s. He looked at the keys as if seeing them for the first time. Then he remembered his teacher’s advice—play the first note for yourself, not for the room—and pressed down.', 'Which choice best describes the overall structure of the text?', '["It describes a character’s sudden nervousness and then a memory that helps him begin.","It compares two teachers’ different methods for performing.","It describes an audience’s reaction to a performance.","It explains why a character decided to stop playing the piano."]'::jsonb, 0, null, 'The text first shows Aziz feeling unfamiliar with his own hands (nervousness), then he recalls advice and starts playing. Only one teacher is mentioned and the audience’s reaction is not described.', 'published'),
  ('rw15', 'rw', 'words-in-context', 3, 'Although critics initially dismissed the architect’s design as merely ______, later scholars recognized that its plain surfaces and simple forms reflected a carefully reasoned philosophy rather than a lack of imagination.', 'Which choice completes the text with the most logical and precise word or phrase?', '["extravagant","chaotic","ornate","austere"]'::jsonb, 3, null, 'The design had “plain surfaces and simple forms,” and critics saw this as a lack of imagination. “Austere” means severely plain. “Extravagant” and “ornate” mean the opposite, and “chaotic” does not fit simple forms.', 'published'),
  ('rw16', 'rw', 'boundaries', 2, 'The physicist Lise Meitner, who helped explain nuclear fission in ______ was long overlooked when the discovery was honored.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1938;","1938,","1938","1938:"]'::jsonb, 1, null, 'The clause “who helped explain nuclear fission in 1938” is extra information set off by a comma before it, so it must be closed by a comma after it before the main verb “was.”', 'published'),
  ('rw17', 'rw', 'inferences', 3, 'Historians once pictured the Silk Road as a single route along which merchants carried goods from China all the way to Europe. However, studies of trade records and archaeological sites show that most merchants traveled only short segments, exchanging goods with other traders in cities such as Samarkand and Bukhara, who then carried them farther. Therefore, ______', 'Which choice most logically completes the text?', '["Samarkand and Bukhara were founded by merchants from Europe.","the movement of goods across Eurasia likely depended on networks of many traders rather than on individual merchants making the entire journey.","few goods from China ever reached Europe.","historians no longer study trade along the Silk Road."]'::jsonb, 1, null, 'If most merchants traveled only short segments and passed goods on, long-distance trade must have relied on chains of many traders. The text does not say goods failed to reach Europe or who founded the cities.', 'published'),
  ('rw18', 'rw', 'transitions', 3, 'Most fish rely heavily on vision to find food. The blind cave form of the Mexican tetra, ______ has lost its functional eyes and instead detects prey with sensitive cells along its body that sense movement in the water.', 'Which choice completes the text with the most logical transition?', '["for example,","by contrast,","similarly,","as a result,"]'::jsonb, 1, null, 'The cave fish does the opposite of what “most fish” do: it does not use vision. “By contrast” signals this difference. “For example” and “similarly” would wrongly suggest it follows the general pattern.', 'published'),
  ('rw19', 'rw', 'rhetorical-synthesis', 3, 'While researching a topic, a student has taken the following notes:
• Muhammad ibn Musa al-Khwarizmi was a 9th-century scholar from Khwarazm, a region in present-day Uzbekistan and Turkmenistan.
• He worked at the House of Wisdom in Baghdad.
• The title of his book on solving equations gave us the word “algebra.”
• The word “algorithm” comes from the Latin form of his name.', 'The student wants to explain how al-Khwarizmi influenced modern vocabulary. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Al-Khwarizmi was a scholar who wrote a book on solving equations.","Al-Khwarizmi came from Khwarazm, a region in present-day Uzbekistan and Turkmenistan.","Al-Khwarizmi, a 9th-century scholar, worked at the House of Wisdom in Baghdad.","Two common words in mathematics come from al-Khwarizmi: “algebra,” from the title of his book on equations, and “algorithm,” from the Latin form of his name."]'::jsonb, 3, null, 'Only the correct choice mentions the words “algebra” and “algorithm,” which is what the goal (influence on vocabulary) requires.', 'published'),
  ('rw20', 'rw', 'form-structure-sense', 3, 'Each of the twelve competing robotics teams had to present ______ design to a panel of engineers before the final round.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they’re","their","its","it’s"]'::jsonb, 2, null, 'The subject is “Each,” which is singular, so the singular possessive pronoun “its” is needed. “It’s” means “it is,” and “their”/“they’re” are plural.', 'published'),
  ('rw21', 'rw', 'command-of-evidence', 3, 'In a survey of 400 students, those who read for pleasure at least 30 minutes a day scored an average of 72 points on a vocabulary test, while those who read less scored an average of 58 points. Based on these results, a student concludes that reading for pleasure causes vocabulary to grow.', 'Which choice best describes a weakness in the student’s conclusion?', '["The vocabulary scores of the two groups were the same.","The survey measured reading time in minutes rather than in hours.","The survey included too many students to give reliable results.","The survey shows a relationship between reading and vocabulary scores but does not show that reading caused the difference."]'::jsonb, 3, null, 'A survey can show that two things occur together (correlation) but not that one causes the other — students with large vocabularies might simply enjoy reading more. The other choices are false or irrelevant.', 'published'),
  ('rw22', 'rw', 'words-in-context', 1, 'The scientist’s notes were so ______ that other researchers could repeat her experiment exactly, step by step.', 'Which choice completes the text with the most logical and precise word or phrase?', '["meticulous","careless","brief","secretive"]'::jsonb, 0, null, 'Notes that allow others to repeat an experiment step by step must be extremely careful and detailed — “meticulous.”', 'published'),
  ('rw23', 'rw', 'boundaries', 2, 'The museum’s newest exhibit features three kinds of ______ ceramics, textiles, and metalwork from across Central Asia.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["objects:","objects","objects;","objects, and"]'::jsonb, 0, null, 'A colon after a complete clause can introduce a list that explains it (“three kinds of objects: ceramics, textiles, and metalwork”). A semicolon must join two complete clauses, which is not the case here.', 'published'),
  ('rw24', 'rw', 'transitions', 2, 'The first version of the app was slow and difficult to use. ______ the developers spent six months redesigning it based on feedback from users.', 'Which choice completes the text with the most logical transition?', '["Nonetheless,","Consequently,","Likewise,","For instance,"]'::jsonb, 1, null, 'The redesign happened because the first version had problems, so the cause-and-effect transition “Consequently” fits.', 'published'),
  ('rw25', 'rw', 'form-structure-sense', 2, 'Neither the coach nor the players ______ expecting the storm to delay the match.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were","was","has been","is"]'::jsonb, 0, null, 'With “neither…nor,” the verb agrees with the nearer subject, “players,” which is plural and in the past context: “were.”', 'published'),
  ('rw26', 'rw', 'words-in-context', 3, 'The diplomat’s statement was deliberately ______: it could be read either as support for the proposal or as a polite refusal, allowing her to avoid committing to a position.', 'Which choice completes the text with the most logical and precise word or phrase?', '["emphatic","hostile","redundant","ambiguous"]'::jsonb, 3, null, 'A statement that can be read two different ways is “ambiguous.” An emphatic statement would be clear and forceful, the opposite of what is described.', 'published'),
  ('rw27', 'rw', 'inferences', 2, 'Snow leopards live in the high mountain ranges of Central and South Asia, where prey is scarce. A single snow leopard may need a territory of hundreds of square kilometers to find enough food. Therefore, protecting snow leopard populations likely requires ______', 'Which choice most logically completes the text?', '["moving snow leopards to lowland forests.","reducing the size of protected areas.","conserving very large areas of mountain habitat.","increasing the number of snow leopards in each square kilometer."]'::jsonb, 2, null, 'Because each animal needs a huge territory, protecting a population requires protecting large areas of its mountain habitat.', 'published'),
  ('rw28', 'rw', 'text-structure', 3, 'Some city planners argue that adding lanes to highways is the best way to reduce traffic. Yet studies in several countries have found that within a few years of new lanes opening, traffic often returns to its previous level, because the extra space encourages more people to drive. Researchers call this pattern “induced demand.”', 'Which choice best describes the function of the first sentence in the text as a whole?', '["It presents a view that the rest of the text challenges.","It proposes a solution that the text supports.","It defines the term “induced demand.”","It summarizes the findings of the studies."]'::jsonb, 0, null, 'The first sentence states the planners’ view; the word “Yet” introduces evidence against it. The studies and the definition come later.', 'published'),
  ('m01', 'math', 'linear-equations', 1, null, 'If 4x + 7 = 31, what is the value of x?', '["4","6","8","9.5"]'::jsonb, 1, null, 'Subtract 7 from both sides: 4x = 24. Divide by 4: x = 6.', 'published'),
  ('m02', 'math', 'ratios', 1, null, 'A shirt originally costs 80,000 so‘m. It is on sale for 25% off. What is the sale price, in so‘m?', '["20,000","55,000","60,000","64,000"]'::jsonb, 2, null, '25% of 80,000 is 20,000. The sale price is 80,000 − 20,000 = 60,000 so‘m. (Or: 75% of 80,000 = 60,000.)', 'published'),
  ('m03', 'math', 'linear-functions', 2, null, 'A taxi charges a fixed fee plus a constant cost per kilometer. A 4-kilometer ride costs 22,000 so‘m and a 10-kilometer ride costs 40,000 so‘m. What is the cost per kilometer, in so‘m?', null, null, array[3000]::numeric[], 'The extra 6 kilometers cost 40,000 − 22,000 = 18,000 so‘m, so each kilometer costs 18,000 ÷ 6 = 3,000 so‘m.', 'published'),
  ('m04', 'math', 'systems', 2, null, 'x + y = 10
x − y = 4
If (x, y) is the solution to the system of equations above, what is the value of xy?', '["12","21","24","28"]'::jsonb, 1, null, 'Add the equations: 2x = 14, so x = 7. Then y = 10 − 7 = 3, and xy = 21.', 'published'),
  ('m05', 'math', 'statistics', 2, null, 'The mean of five numbers is 12. When a sixth number is added, the mean of the six numbers is 13. What is the sixth number?', null, null, array[18]::numeric[], 'The five numbers sum to 5 × 12 = 60. The six numbers sum to 6 × 13 = 78. The sixth number is 78 − 60 = 18.', 'published'),
  ('m06', 'math', 'nonlinear-equations', 3, null, 'In the equation x² + bx + 36 = 0, b is a positive constant. If the equation has exactly one real solution, what is the value of b?', null, null, array[12]::numeric[], 'A quadratic has exactly one real solution when its discriminant is 0: b² − 4(1)(36) = 0, so b² = 144 and b = 12 (since b > 0).', 'published'),
  ('m07', 'math', 'right-triangles-trig', 3, null, 'In right triangle ABC, angle C measures 90°. If sin A = 3/5, what is the value of tan B?', '["3/5","3/4","4/5","4/3"]'::jsonb, 3, null, 'sin A = 3/5 means the side opposite A is 3 and the hypotenuse is 5, so the remaining leg is 4. Angle B is opposite the side of length 4 and adjacent to the side of length 3, so tan B = 4/3.', 'published'),
  ('m08', 'math', 'linear-equations', 1, null, 'What value of x satisfies the equation 2(x + 3) = 14?', '["4","5","7","8.5"]'::jsonb, 0, null, 'Divide both sides by 2: x + 3 = 7. Subtract 3: x = 4.', 'published'),
  ('m09', 'math', 'ratios', 1, null, 'A recipe uses 3 cups of flour for every 2 cups of milk. How many cups of flour are needed for 8 cups of milk?', '["10","11","12","16"]'::jsonb, 2, null, '8 cups of milk is 4 times 2 cups, so the flour is 4 × 3 = 12 cups.', 'published'),
  ('m10', 'math', 'area-volume', 1, null, 'A rectangle has a length of 12 centimeters and a width of 5 centimeters. What is the perimeter of the rectangle, in centimeters?', null, null, array[34]::numeric[], 'Perimeter = 2(length + width) = 2(12 + 5) = 34 cm.', 'published'),
  ('m11', 'math', 'linear-inequalities', 2, null, 'Which of the following values of x is a solution to the inequality 5x − 3 > 17?', '["2","3","4","5"]'::jsonb, 3, null, 'Add 3: 5x > 20. Divide by 5: x > 4. Only 5 is greater than 4 (4 itself is not a solution because the inequality is strict).', 'published'),
  ('m12', 'math', 'equivalent-expressions', 2, null, 'Which expression is equivalent to (x + 4)(x − 4)?', '["x² − 16","x² + 16","x² − 8x − 16","x² − 8"]'::jsonb, 0, null, 'This is a difference of squares: (x + 4)(x − 4) = x² − 4x + 4x − 16 = x² − 16.', 'published'),
  ('m13', 'math', 'probability', 2, null, 'A bag contains 6 red marbles, 4 blue marbles, and 10 green marbles. If one marble is chosen at random, what is the probability that it is blue?', '["1/4","1/5","1/3","2/5"]'::jsonb, 1, null, 'There are 6 + 4 + 10 = 20 marbles, and 4 are blue. The probability is 4/20 = 1/5.', 'published'),
  ('m14', 'math', 'lines-angles-triangles', 2, null, 'Two angles of a triangle measure 48° and 67°. What is the measure, in degrees, of the third angle?', null, null, array[65]::numeric[], 'The angles of a triangle sum to 180°: 180 − 48 − 67 = 65.', 'published'),
  ('m15', 'math', 'circles', 2, null, 'A circle in the xy-plane has the equation (x − 3)² + (y + 2)² = 25. Which of the following points lies on the circle?', '["(3, −2)","(6, 2)","(8, 3)","(0, 0)"]'::jsonb, 1, null, 'Substitute each point. For (6, 2): (6 − 3)² + (2 + 2)² = 9 + 16 = 25 ✓. The point (3, −2) is the center, (8, 3) gives 50, and (0, 0) gives 13.', 'published'),
  ('m16', 'math', 'linear-functions', 2, null, 'Line ℓ passes through the points (1, 5) and (4, 14). What is the y-coordinate of the y-intercept of line ℓ?', null, null, array[2]::numeric[], 'Slope = (14 − 5)/(4 − 1) = 3. Using y = 3x + b with (1, 5): 5 = 3 + b, so b = 2.', 'published'),
  ('m17', 'math', 'nonlinear-functions', 3, null, 'The population of a town is modeled by P(t) = 20,000(1.05)ᵗ, where t is the number of years after 2020. Which statement is true according to the model?', '["The population was 21,000 in 2020.","The population increases by 1,050 people each year.","The population increases by 105% each year.","The population increases by 5% each year."]'::jsonb, 3, null, 'A growth factor of 1.05 means each year the population is multiplied by 1.05 — a 5% increase. In 2020 (t = 0) the population was 20,000.', 'published'),
  ('m18', 'math', 'systems', 3, null, '3x + 2y = 7
6x + ky = 10
In the system of equations above, k is a constant. For what value of k does the system have no solution?', null, null, array[4]::numeric[], 'Multiplying the first equation by 2 gives 6x + 4y = 14. If k = 4, the left sides match but 14 ≠ 10, so the lines are parallel and there is no solution.', 'published'),
  ('m19', 'math', 'nonlinear-equations', 3, null, 'What is the sum of the solutions to the equation 2x² − 12x + 7 = 0?', null, null, array[6]::numeric[], 'For ax² + bx + c = 0, the sum of the solutions is −b/a = −(−12)/2 = 6.', 'published'),
  ('m20', 'math', 'statistics', 3, null, 'A data set consists of the values 3, 5, 8, 8, and 11. If the value 11 is replaced with 26, which statement is true?', '["The mean stays the same and the median increases.","Neither the mean nor the median changes.","Both the mean and the median increase.","The mean increases and the median stays the same."]'::jsonb, 3, null, 'The sum grows by 15, so the mean increases (from 7 to 10). The middle value of the ordered list is still 8, so the median does not change.', 'published'),
  ('m21', 'math', 'area-volume', 3, null, 'A right circular cone has a radius of 6 and a volume of 96π. What is the height of the cone? (The volume of a cone is V = ⅓πr²h.)', null, null, array[8]::numeric[], '96π = ⅓π(6²)h = 12πh, so h = 96 ÷ 12 = 8.', 'published'),
  ('m22', 'math', 'linear-equations', 1, null, 'If x/3 = 7, what is the value of 2x?', '["14","21","42","63"]'::jsonb, 2, null, 'x = 21, so 2x = 42.', 'published'),
  ('m23', 'math', 'ratios', 2, null, 'A car travels 180 kilometers in 2.5 hours at a constant speed. At this speed, how many kilometers will the car travel in 4 hours?', null, null, array[288]::numeric[], 'Speed = 180 ÷ 2.5 = 72 km per hour. In 4 hours: 72 × 4 = 288 km.', 'published'),
  ('m24', 'math', 'equivalent-expressions', 2, null, 'Which expression is equivalent to 3x(2x − 5) + 4x?', '["6x² − 11x","6x² − 19x","6x² − 15x + 4","5x² − 11x"]'::jsonb, 0, null, '3x(2x − 5) = 6x² − 15x. Adding 4x gives 6x² − 11x.', 'published'),
  ('m25', 'math', 'right-triangles-trig', 1, null, 'A right triangle has legs of length 6 and 8. What is the length of the hypotenuse?', null, null, array[10]::numeric[], 'By the Pythagorean theorem: √(6² + 8²) = √100 = 10.', 'published'),
  ('m26', 'math', 'linear-functions', 2, null, 'The total cost C, in so‘m, of printing n posters is given by C = 4,500n + 30,000. What is the best interpretation of 30,000 in this context?', '["The total cost of printing 4,500 posters","The cost of printing each poster","The number of posters printed","A fixed cost that does not depend on the number of posters"]'::jsonb, 3, null, 'When n = 0, C = 30,000, so 30,000 is the cost even before any poster is printed — a fixed cost. 4,500 is the cost per poster.', 'published'),
  ('m27', 'math', 'nonlinear-functions', 3, null, 'The function f is defined by f(x) = x² − 6x + 11. What is the minimum value of f(x)?', null, null, array[2]::numeric[], 'Complete the square: f(x) = (x − 3)² + 2. The square is never negative, so the minimum is 2, at x = 3.', 'published'),
  ('m28', 'math', 'ratios', 2, null, 'In a class, 60% of the students play a sport. Of the students who play a sport, 25% play football. What percent of the whole class plays football?', null, null, array[15]::numeric[], '25% of 60% is 0.25 × 0.60 = 0.15, or 15% of the class.', 'published')
on conflict (id) do nothing;
